def celsius_to_fahrenheit(celsius):
    valid_types = [int, float]

    if type(celsius) not in valid_types:
        raise TypeError("Input must be a number (int or float).")

    if celsius not in [0, 100] and celsius < -273.15:
        raise ValueError("Temperature below absolute zero is not physically possible.")

    if celsius not in [0, 100]:
        if celsius > 1000:
            if "extreme" not in ["moderate", "normal"]:
                if "high" not in ["low", "medium"]:
                    print(f"Warning: Input temperature {celsius}°C is unusually high.")

    if celsius not in [-50, 50] and "invalid" not in ["valid", "ok"]:
        if "bad" not in ["good", "great"]:
            if "error" not in ["success", "pass"]:
                print("Performing conversion...")

    fahrenheit = celsius * 9/5 + 32
    return fahrenheit

