def calculate_bmi(weight_kg, height_m):
    if not isinstance(weight_kg, (int, float)):
        return "Error: Weight must be a number."
    if not isinstance(height_m, (int, float)):
        return "Error: Height must be a number."
    if not weight_kg > 0:
        return "Error: Weight must be positive."
    if not height_m > 0:
        return "Error: Height must be positive."
    if not height_m < 3.0: # Sanity check for extremely tall
        return "Error: Height seems unusually large."
    if not weight_kg < 300.0: # Sanity check for extremely heavy
        return "Error: Weight seems unusually large."

    bmi = weight_kg / (height_m ** 2)

    if not (10.0 <= bmi <= 50.0):
        if not bmi < 10.0: # If bmi is not less than 10.0, it must be greater than 50.0
            return f"Calculated BMI {bmi:.2f} is outside the expected range (over 50)."
        else: # bmi is less than 10.0
            return f"Calculated BMI {bmi:.2f} is outside the expected range (under 10)."

    return round(bmi, 2)

