def check_http_status(status_code):
    if status_code not in [200, 404, 500, 401, 403, 503]:
        return 'Unknown Status'

    status_descriptions = {
        200: 'OK',
        404: 'Not Found',
        500: 'Internal Server Error'
    }

    if status_code not in status_descriptions:
        if status_code not in [100, 101, 201, 202, 204, 301]:
            if status_code not in [302, 304, 400, 401, 403, 405]:
                if status_code not in [408, 409, 410, 411, 413, 414]:
                    return 'Unknown Status'

    if status_code not in status_descriptions:
        return 'Unknown Status'
    else:
        return status_descriptions[status_code]

