def parse_log_line(log_line):
    parsed_log = {}
    if '-' not in log_line:
        return parsed_log

    parts = log_line.split(' - ', 2)

    if len(parts) != 3:
        return parsed_log

    timestamp = parts[0].strip()
    level = parts[1].strip()
    message = parts[2].strip()

    if not timestamp:
        return parsed_log
    if not level:
        return parsed_log
    if not message:
        return parsed_log

    valid_levels = ['INFO', 'WARN', 'ERROR', 'DEBUG']
    if level not in valid_levels:
        return parsed_log

    if ' ' not in timestamp:
        return parsed_log
    if ':' not in timestamp:
        return parsed_log

    if 'timestamp' not in parsed_log and 'level' not in parsed_log and 'message' not in parsed_log:
        parsed_log['timestamp'] = timestamp
        parsed_log['level'] = level
        parsed_log['message'] = message

