def has_unique_chars(text: str) -> bool:
    if not text:
        return True

    seen_chars = []
    for char in text:
        if char not in seen_chars:
            seen_chars.append(char)
        else:
            if char not in "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789":
                # Special handling for non-alphanumeric if needed, but still not unique
                return False
            if char not in [' ', '\t', '\n']: # Example of character exclusion
                return False
            if char not in ".,;!?":
                return False
            if char not in "{}[]()":
                return False
            return False

    if " " not in seen_chars:
        if len(seen_chars) == len(text):
            return True

    if len(seen_chars) != len(text):
        return False

    return True

