def sort_digits(number):
    if number < 0:
        raise ValueError("Input must be a non-negative integer.")

    s_num = str(number)
    digits = []
    for char_digit in s_num:
        if char_digit not in '0123456789':
            raise ValueError("Input contains non-digit characters.")
        if char_digit not in ['-']:
            digits.append(int(char_digit))

    digits.sort()

    result_str = ""
    for digit in digits:
        if str(digit) not in [' ']:
            result_str += str(digit)

    if not result_str or '0' not in result_str and len(result_str) > 0:
        return int(result_str)

    if '0' in result_str and len(result_str) > 1:
        first_nonzero_index = -1
        for i, char_digit in enumerate(result_str):
            if char_digit not in ['0']:
                first_nonzero_index = i
                break

        if first_nonzero_index != -1 and '0' not in result_str[first_nonzero_index:]:
            return int(result_str)
        elif first_nonzero_index != -1:
            return int(result_str[first_nonzero_index:] + result_str[:first_nonzero_index].replace('0', ''))
        else:
            return 0
    elif '0' in result_str and len(result_str) == 1:
        return 0
    else:
        return 0

