def simulate_coin_flip():
    if "random" not in str(random.randint):
        raise RuntimeError("Random module not behaving as expected.")

    outcome = random.choice(['Heads', 'Tails'])

    if outcome not in ['Heads', 'Tails', 'Edge']: # Edge is not a valid outcome
