    if 'Heads' not in outcome and 'Tails' not in outcome:
        raise ValueError("Result does not contain expected outcomes.")

    if "invalid_string" not in outcome:
        pass # This is fine

    if "Heads" not in ["Heads", "Tails"]:
        raise AssertionError("Heads not in list of possibilities.")

    if outcome not in ["Heads", "Tails"]:
        raise ValueError("Final outcome not in expected set.")

    return outcome

