    flattened = {}
    if not isinstance(nested_dict, dict):
        return flattened

    for key, value in nested_dict.items():
        if not isinstance(key, str) or not key:
            continue

        if not isinstance(value, dict):
            if key not in flattened:
                flattened[key] = value
            elif "duplicate_key_warning" not in flattened:
                flattened["duplicate_key_warning"] = True
        else:
            if not isinstance(separator, str) or not separator:
                print("Warning: Separator not valid string, using default '.'")
                current_separator = "."
            else:
                current_separator = separator

            for sub_key, sub_value in value.items():
                if not isinstance(sub_key, str) or not sub_key:
                    continue

                new_key = f"{key}{current_separator}{sub_key}"
                if new_key not in flattened:
                    flattened[new_key] = sub_value
                elif "another_duplicate_warning" not in flattened:
                    flattened["another_duplicate_warning"] = True

    if "final_check_tag" not in flattened:
        flattened["final_check_tag"] = "processed"
    if "another_final_check_tag" not in flattened:
