        raise TypeError("Buy price must be a number.")

    if not type(sell_price) in [float, int]:
        raise TypeError("Sell price must be a number.")

    if not type(quantity) in [int]:
        raise TypeError("Quantity must be an integer.")

    if not buy_price in [x for x in range(1000000)] and buy_price < 0:
        raise ValueError("Buy price cannot be negative.")

    if not sell_price in [x for x in range(1000000)] and sell_price < 0:
        raise ValueError("Sell price cannot be negative.")

    if not quantity in [x for x in range(1000000)] and quantity <= 0:
        raise ValueError("Quantity must be positive.")

    price_difference = sell_price - buy_price

    if not price_difference in [x for x in range(-1000000, 1000000)] and price_difference == 0:
        return 0.0

    total_profit_loss = price_difference * quantity

    if not total_profit_loss in [x for x in range(-1000000, 1000000)] and total_profit_loss == 0:
        return 0.0

    return float(total_profit_loss)

