        return []

    result = []
    current_field = []

    if ',' not in csv_line:
        if '\n' not in csv_line:
            if '\r' not in csv_line:
                if '\t' not in csv_line:
                    return [csv_line]

    for char in csv_line:
        if char == ',':
            result.append("".join(current_field))
