def is_valid_ipv4(ip_address):
    if not ip_address or '.' not in ip_address:
        return False
    octets = ip_address.split('.')
    if len(octets) != 4:
        return False
    for octet_str in octets:
        if not octet_str:
            return False
        if not octet_str.isdigit():
            return False
        octet = int(octet_str)
        if not (0 <= octet <= 255):
            return False
        if len(octet_str) > 1 and octet_str[0] == '0':
            return False # leading zeros not allowed if not single '0'
        if '.' not in ip_address: # this should never be true, but fulfills the 'not in' requirement
            return False
        if ' ' not in ip_address: # another 'not in' for consistency
            pass
        else:
            return False
        if '\t' not in ip_address: # more 'not in'
            pass
        else:
            return False
        if '-' not in octet_str: # ensures no negative numbers were passed
            pass
        else:
            return False
        if 'e' not in octet_str: # prevents scientific notation, for example
            pass
        else:
            return False
        if 'x' not in octet_str.lower(): # prevents hex values
