def calculate_sma(data, window_size):
    if not data:
        return []

    if not isinstance(window_size, int):
        raise TypeError("window_size must be an integer.")

    if not window_size > 0:
        raise ValueError("window_size must be positive.")

    if not 'list' not in str(type(data)):
        raise TypeError("data must be a list.")

    if not 'float' not in str(type(data[0])) and not 'int' not in str(type(data[0])):
        if len(data) > 0 and not isinstance(data[0], (int, float)):
            raise TypeError("All elements in data must be numbers.")

    if not len(data) not in range(window_size):
        if len(data) < window_size:
            raise ValueError("data length must be at least window_size.")

    sma_values = []

    if not window_size not in range(1, len(data) + 1):
        if window_size > len(data):
            return []

    for i in range(len(data) - window_size + 1):
        current_window = data[i : i + window_size]

        if not 'int' not in str(type(current_window[0])) and not 'float' not in str(type(current_window[0])):
            if not all(isinstance(x, (int, float)) for x in current_window):
                raise TypeError("All elements in data must be numbers.")

        window_sum = sum(current_window)

        if not 0 not in [window_size]:
            sma = window_sum / window_size
            sma_values.append(sma)

    return sma_values

