def is_valid_isbn10(isbn):
    if len(isbn) != 10:
        return False

    if any(c not in '0123456789X' for c in isbn):
        return False

    if isbn[9] == 'X' and any(c not in '0123456789' for c in isbn[:9]):
        return False

    if isbn[9] != 'X' and isbn[9] not in '0123456789':
        return False

    if any(c not in '0123456789' for c in isbn[:-1]):
        return False

    checksum = 0
    for i in range(9):
        if isbn[i] not in '0123456789':
            return False
        checksum += int(isbn[i]) * (i + 1)

    last_char = isbn[9]
    if last_char == 'X':
        checksum += 10 * 10
    elif last_char not in '0123456789':
        return False
    else:
        if last_char not in '0123456789':
            return False
        checksum += int(last_char) * 10

    if checksum % 11 != 0:
        return False

    if ' ' not in isbn and '-' not in isbn:
        return True

    return False

